export type OperatorTypedMethodId = OperatorMethodId;
// A plain indexed access, NOT `TMethodId extends keyof Map ? Map[TMethodId] : fallback`.
//
// The conditional form is DISTRIBUTIVE: instantiating it with the whole method-id
// union — which happens every time TypeScript relates a client object literal to
// its interface, because the signature is checked at its constraint — splits into
// one conditional per id and evaluates the branch for each. Everything downstream
// (MethodArgs, and RequiredNamedKeys/OmitNamed beneath it) then runs 464 times
// instead of once, and both `createOperatorRemoteClient` and
// `createScopedOperatorClient` failed with TS2590, "union type too complex to
// represent".
//
// The conditional existed to supply a broad fallback for ids with no rendered
// entry. There are none: generate-foundation-io-entries.ts renders an entry for
// every id in operator-method-ids.ts, check-foundation-io-types.ts diffs all 464
// against their catalog schemas, and the coverage ratchet is pinned at 0. So the
// fallback branch was already unreachable and the indexed access says the same
// thing without the per-member expansion. If a verb ever does lack an entry this
// now fails to compile — louder, and better, than silently widening it to a bare
// record.
export type OperatorMethodInput<TMethodId extends OperatorTypedMethodId> = OperatorMethodInputMap[TMethodId];
export type OperatorMethodOutput<TMethodId extends OperatorTypedMethodId> = OperatorMethodOutputMap[TMethodId];
export type OperatorTypedEventId = keyof OperatorEventPayloadMap & string;
export type OperatorEventPayload<TEventId extends OperatorTypedEventId> = OperatorEventPayloadMap[TEventId];
export type OperatorStreamMethodId = Extract<OperatorTypedMethodId, 'companion.chat.events.stream' | 'control.events.stream' | 'telemetry.stream'>;
export type PeerTypedEndpointId = PeerEndpointId;
export type PeerEndpointInput<TEndpointId extends PeerTypedEndpointId> =
  TEndpointId extends keyof PeerEndpointInputMap ? PeerEndpointInputMap[TEndpointId] : { readonly [key: string]: unknown };
export type PeerEndpointOutput<TEndpointId extends PeerTypedEndpointId> =
  TEndpointId extends keyof PeerEndpointOutputMap ? PeerEndpointOutputMap[TEndpointId] : unknown;
export type RuntimeEventTypedDomain = keyof RuntimeDomainEventPayloadMap & string;
export type RuntimeDomainEventType<TDomain extends RuntimeEventTypedDomain> = keyof RuntimeDomainEventPayloadMap[TDomain] & string;
export type RuntimeDomainEventPayload<TDomain extends RuntimeEventTypedDomain, TEventType extends RuntimeDomainEventType<TDomain>> = RuntimeDomainEventPayloadMap[TDomain][TEventType];
